import json

from lfx.custom.custom_component.component import Component
from lfx.io import BoolInput, HandleInput, Output
from lfx.schema.message import Message


class WhatsAppEntradaEvolution(Component):
    display_name = "WhatsApp Entrada (Evolution)"
    description = (
        "Lê o payload do Webhook da Evolution API, filtra eventos que não são mensagens de clientes "
        "e entrega o texto ao Agente. Usa o telefone do cliente como sessão (memória por cliente)."
    )
    icon = "MessageCircle"
    name = "WhatsAppEntradaEvolution"

    inputs = [
        HandleInput(
            name="payload",
            display_name="Payload do Webhook",
            input_types=["Data", "JSON"],
            info="Conecte a saída do componente Webhook.",
            required=False,
        ),
        BoolInput(
            name="ignorar_grupos",
            display_name="Ignorar grupos",
            value=True,
            info="Não responde mensagens enviadas em grupos.",
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Mensagem", name="mensagem", method="build_message"),
    ]

    def _parar(self, motivo: str) -> Message:
        self.status = f"Ignorado: {motivo}"
        self.stop("mensagem")
        return Message(text="")

    @staticmethod
    def _escolher_jid(key: dict) -> str:
        candidatos = [key.get("remoteJid") or "", key.get("remoteJidAlt") or ""]
        for jid in candidatos:
            if jid.endswith("@s.whatsapp.net"):
                return jid
        return candidatos[0]

    async def build_message(self) -> Message:
        raw = self.payload
        body = getattr(raw, "data", raw) if raw is not None else None
        if not isinstance(body, dict) or not body:
            return self._parar("sem payload (modo Playground ou webhook vazio)")

        # Se o Webhook não conseguiu ler o JSON, ele entrega {"payload": "<texto>"}.
        if set(body.keys()) == {"payload"} and isinstance(body["payload"], str):
            try:
                body = json.loads(body["payload"], strict=False)
            except json.JSONDecodeError:
                return self._parar("payload inválido")

        # A Evolution envia o evento direto; alguns proxies embrulham em "body".
        if "body" in body and isinstance(body["body"], dict):
            body = body["body"]

        evento = str(body.get("event", "")).lower()
        if evento and evento not in ("messages.upsert", "messages_upsert"):
            return self._parar(f"evento {evento}")

        data = body.get("data") or {}
        key = data.get("key") or {}
        if key.get("fromMe"):
            return self._parar("mensagem enviada pelo próprio número")

        jid = self._escolher_jid(key)
        if not jid:
            return self._parar("remetente não identificado")
        if self.ignorar_grupos and jid.endswith("@g.us"):
            return self._parar("mensagem de grupo")

        msg = data.get("message") or {}
        tipo = data.get("messageType", "")
        texto = (
            msg.get("conversation")
            or (msg.get("extendedTextMessage") or {}).get("text")
            or (msg.get("imageMessage") or {}).get("caption")
            or (msg.get("videoMessage") or {}).get("caption")
            or ""
        ).strip()

        if not texto:
            if tipo == "audioMessage":
                texto = "[O cliente enviou um áudio. Peça gentilmente que ele escreva a mensagem em texto.]"
            elif tipo == "imageMessage":
                texto = "[O cliente enviou uma imagem sem legenda. Peça que descreva por texto o que precisa.]"
            else:
                return self._parar(f"tipo de mensagem não suportado ({tipo})")

        nome = data.get("pushName") or "Cliente"

        # Sessão = telefone do cliente -> o Agente busca a memória desta conversa.
        self.graph.session_id = jid
        self.update_ctx(
            {
                "whatsapp": {
                    "jid": jid,
                    "numero": jid.split("@")[0],
                    "instancia": body.get("instance", ""),
                    "server_url": body.get("server_url", ""),
                    "apikey": body.get("apikey", ""),
                    "nome": nome,
                }
            }
        )

        message = await Message.create(
            text=texto,
            sender="User",
            sender_name=nome,
            session_id=jid,
        )
        stored = await self.send_message(message)
        self.status = f"{nome} ({jid}): {texto}"
        return stored or message
